CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS ranks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(64) NOT NULL UNIQUE,star_count smallint NOT NULL UNIQUE CHECK(star_count BETWEEN 1 AND 27),star_color varchar(16) NOT NULL DEFAULT '#8B7CF6',icon varchar(32) NOT NULL DEFAULT '⭐',microphone_duration integer NOT NULL DEFAULT 300 CHECK(microphone_duration>=0),permissions jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),username varchar(32) NOT NULL UNIQUE,password_hash text,is_guest boolean NOT NULL DEFAULT false,rank_id uuid NOT NULL REFERENCES ranks(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(48) NOT NULL UNIQUE,description varchar(180) NOT NULL DEFAULT '',is_locked boolean NOT NULL DEFAULT false,max_members integer NOT NULL DEFAULT 250 CHECK(max_members BETWEEN 2 AND 5000),created_at timestamptz NOT NULL DEFAULT now());
